(function(){self.onmessage=async e=>{let t=e.data;try{switch(t.type){case`deriveKey`:{let e=new TextEncoder,n=await crypto.subtle.importKey(`raw`,e.encode(t.password),`PBKDF2`,!1,[`deriveKey`]),r=await crypto.subtle.deriveKey({name:`PBKDF2`,salt:t.salt,iterations:6e5,hash:`SHA-256`},n,{name:`AES-GCM`,length:256},!1,[`encrypt`,`decrypt`]);self.postMessage({type:`deriveKey`,key:r,id:t.id});break}case`encrypt`:{let e=await crypto.subtle.encrypt({name:`AES-GCM`,iv:t.nonce,tagLength:128},t.key,t.data);self.postMessage({type:`encrypt`,data:e,id:t.id},[e]);break}case`decrypt`:{let e=await crypto.subtle.decrypt({name:`AES-GCM`,iv:t.nonce,tagLength:128},t.key,t.data);self.postMessage({type:`decrypt`,data:e,id:t.id},[e]);break}}}catch(e){self.postMessage({type:`error`,error:e.message,id:t.id})}}})();